CREATE DATABASE IF NOT EXISTS sortify; USE sortify;
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL CHECK(price>=0),rating DECIMAL(2,1) NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 5),popularity INT NOT NULL DEFAULT 0 CHECK(popularity>=0),discount DECIMAL(5,2) NOT NULL DEFAULT 0 CHECK(discount BETWEEN 0 AND 100),stock INT NOT NULL DEFAULT 0 CHECK(stock>=0),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
